function renderList(array $items): string {
    $html = "<ul>";
    foreach ($items as $item) {
        $html .= "<li>" . $item . "</li>";
    }
    return $html . "</ul>";
}

function renderList(array $items): string {
    foreach ($items as $item) {
        $html = "<li>" . htmlspecialchars($item) . "</li>";
    }
    return "<ul>" . $html . "</ul>";
}

